<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('quotations.view');$bid=(int)$u['business_id'];$q=trim((string)($_GET['q']??''));$sql='SELECT q.*,c.name customer FROM quotations q JOIN customers c ON c.id=q.customer_id WHERE q.business_id=?';$args=[$bid];if($q!==''){$sql.=' AND (q.quotation_number LIKE ? OR c.name LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%');}$sql.=' ORDER BY q.quotation_date DESC,q.id DESC';$s=db()->prepare($sql);$s->execute($args);$rows=$s->fetchAll();page_start('Quotations','quotations');module_css('quotations');?><div class="section-head"><div><span class="eyebrow">SALES</span><h1>Quotations</h1><p>Estimates stay intact when an accepted quote becomes an invoice.</p></div><a class="button primary" href="quotation-create.php"><i class="ti ti-plus"></i> New quotation</a></div><div class="content-card"><form class="toolbar"><input class="search" name="q" value="<?=e($q)?>" placeholder="Search quote or customer"><button class="button secondary">Search</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>QUOTATION</th><th>CUSTOMER</th><th>DATE</th><th>VALID UNTIL</th><th>TOTAL</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a class="table-strong" href="quotation-view.php?id=<?=(int)$r['id']?>"><?=e($r['quotation_number'])?></a></td><td><?=e($r['customer'])?></td><td><?=fmt_date($r['quotation_date'])?></td><td><?=fmt_date($r['valid_until'])?></td><td class="table-strong"><?=money($r['total'])?></td><td><span class="status <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><a class="link-button" href="quotation-view.php?id=<?=(int)$r['id']?>">Open</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-row">No quotations yet. Create a quotation for a customer to get started.</td></tr><?php endif?></tbody></table></div></div><?php page_end();
